from pathlib import Path
import json,sys
expected=['S1_8K_OK','TEST=C005_P10','AP_READY=1','BAD_IRQ=01','BAD_MIXED=1','BAD_FINAL=1','GOOD_IRQ=01','GOOD_IRQ_SAW_HOLDING=1','GOOD_MIXED=0','GOOD_FINAL=1','AP_DONE=1','DONE']
trace=Path(sys.argv[1]).read_text(encoding='ascii',errors='replace').splitlines();checks={'trace_exact':trace==expected,'two_cpu_plus_real_irq':all(x in trace for x in ['AP_READY=1','BAD_IRQ=01','GOOD_IRQ=01','AP_DONE=1']),'separate_boundaries_allow_mixed':'BAD_MIXED=1' in trace and 'BAD_FINAL=1' in trace,'shared_boundary_composes':all(x in trace for x in ['GOOD_IRQ_SAW_HOLDING=1','GOOD_MIXED=0','GOOD_FINAL=1'])};out={'format':'C005_P10_EVALUATION_V1','passed':all(checks.values()),'checks':checks,'trace':trace};Path(sys.argv[2]).write_text(json.dumps(out,indent=2)+'\n',encoding='utf-8',newline='\n');print(json.dumps(out,indent=2));raise SystemExit(0 if out['passed'] else 1)
